-- Additive migration: existing Election Atlas tables and observations are preserved.
PRAGMA foreign_keys=ON;
CREATE TABLE companies(symbol TEXT PRIMARY KEY,name TEXT NOT NULL,cik TEXT,sector TEXT NOT NULL,data TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX companies_name ON companies(name);
CREATE TABLE stock_symbols(symbol TEXT PRIMARY KEY,company_symbol TEXT REFERENCES companies(symbol),exchange TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('stock','etf','index')));
CREATE TABLE market_sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,display_policy TEXT NOT NULL,persistence_allowed INTEGER NOT NULL DEFAULT 0 CHECK(persistence_allowed IN (0,1)),source_url TEXT NOT NULL);
CREATE TABLE market_observations(id TEXT PRIMARY KEY,symbol TEXT NOT NULL REFERENCES stock_symbols(symbol),source_id TEXT NOT NULL REFERENCES market_sources(id),observed_at TEXT NOT NULL,data TEXT NOT NULL,UNIQUE(symbol,source_id,observed_at));
CREATE INDEX market_retention ON market_observations(observed_at);
CREATE TRIGGER market_rights_guard BEFORE INSERT ON market_observations WHEN COALESCE((SELECT persistence_allowed FROM market_sources WHERE id=NEW.source_id),0) != 1 BEGIN SELECT RAISE(ABORT,'Market persistence is not authorized for this source'); END;
CREATE TABLE article_sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,rights TEXT NOT NULL);
CREATE TABLE articles(id TEXT PRIMARY KEY,url TEXT NOT NULL UNIQUE,title TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES article_sources(id),published_at TEXT,observed_at TEXT NOT NULL,category TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX articles_category_date ON articles(category,published_at DESC);
CREATE INDEX articles_retention ON articles(observed_at);
CREATE TABLE story_clusters(id TEXT PRIMARY KEY,headline TEXT NOT NULL,score REAL NOT NULL,updated_at TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX stories_rank ON story_clusters(score DESC);
CREATE TABLE story_articles(story_id TEXT NOT NULL REFERENCES story_clusters(id) ON DELETE CASCADE,article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,PRIMARY KEY(story_id,article_id));
CREATE TABLE topics(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE company_article_links(symbol TEXT NOT NULL REFERENCES companies(symbol),article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,method TEXT NOT NULL,PRIMARY KEY(symbol,article_id));
CREATE INDEX company_links_article ON company_article_links(article_id);
CREATE TABLE economic_series(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL,frequency TEXT NOT NULL,source_url TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE economic_observations(series_id TEXT NOT NULL REFERENCES economic_series(id),date TEXT NOT NULL,value REAL NOT NULL,realtime_start TEXT,realtime_end TEXT,observed_at TEXT NOT NULL,revised INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(series_id,date));
CREATE INDEX economy_dates ON economic_observations(series_id,date DESC);
CREATE TABLE economic_releases(id TEXT PRIMARY KEY,date TEXT NOT NULL,name TEXT NOT NULL,source_url TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX releases_date ON economic_releases(date);
CREATE TABLE sec_filings(id TEXT PRIMARY KEY,symbol TEXT NOT NULL REFERENCES companies(symbol),form TEXT NOT NULL,filed TEXT NOT NULL,source_url TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX filings_company_date ON sec_filings(symbol,filed DESC);
CREATE TABLE provider_syncs(id TEXT PRIMARY KEY,status TEXT NOT NULL,last_success TEXT,last_attempt TEXT,next_attempt TEXT,data TEXT NOT NULL);
CREATE TABLE data_quality_events(id TEXT PRIMARY KEY,provider_id TEXT NOT NULL REFERENCES provider_syncs(id),severity TEXT NOT NULL,observed_at TEXT NOT NULL,detail TEXT NOT NULL);
CREATE INDEX quality_retention ON data_quality_events(observed_at);
CREATE TABLE pulse_cache(key TEXT PRIMARY KEY,data TEXT NOT NULL,updated_at TEXT NOT NULL);
